// Example: styling based on state
function StyledButton() {
  const { theme, toggleTheme } = useContext(ThemeContext);
  return (
    <button 
      style={{
        backgroundColor: theme === 'dark' ? '#333' : '#eee',
        color: theme === 'dark' ? '#fff' : '#000'
      }}
      onClick={toggleTheme}
    >
      Toggle Theme
    </button>
  );
}

